import React, { useState, useEffect } from "react";
import { Button } from "./ui/button";
import { Badge } from "./ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "./ui/card";
import { ArrowLeft, Calendar, Users, Clock, Code, Target, Trophy, ChevronRight, ExternalLink } from "lucide-react";
import { projects } from "../data/mock";
import { useNavigate } from "react-router-dom";

const ProjectsShowcase = () => {
  const [selectedProject, setSelectedProject] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [filteredProjects, setFilteredProjects] = useState(projects);
  const [isLoaded, setIsLoaded] = useState(false);
  
  const navigate = useNavigate();

  useEffect(() => {
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (selectedCategory === "All") {
      setFilteredProjects(projects);
    } else {
      setFilteredProjects(projects.filter(project => project.category === selectedCategory));
    }
  }, [selectedCategory]);

  const categories = ["All", ...new Set(projects.map(project => project.category))];

  const getStatusColor = (status) => {
    return status === "Completed" ? "bg-green-400/20 text-green-400 border-green-400/30" 
                                  : "bg-yellow-400/20 text-yellow-400 border-yellow-400/30";
  };

  const getCategoryColor = (category) => {
    switch (category) {
      case "Autonomous Systems": return "bg-blue-400/20 text-blue-400 border-blue-400/30";
      case "AI & Environment": return "bg-green-400/20 text-green-400 border-green-400/30";
      case "Industrial Automation": return "bg-orange-400/20 text-orange-400 border-orange-400/30";
      case "IoT & Smart Systems": return "bg-purple-400/20 text-purple-400 border-purple-400/30";
      case "Education": return "bg-pink-400/20 text-pink-400 border-pink-400/30";
      case "Precision Engineering": return "bg-teal-400/20 text-teal-400 border-teal-400/30";
      default: return "bg-gray-400/20 text-gray-400 border-gray-400/30";
    }
  };

  const openProjectDetail = (project) => {
    setSelectedProject(project);
  };

  const closeProjectDetail = () => {
    setSelectedProject(null);
  };

  return (
    <div className={`min-h-screen bg-black text-white transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`}>
      {/* Header */}
      <header className="sticky top-0 z-40 bg-black/80 backdrop-blur-md border-b border-gray-800">
        <div className="container mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <Button 
                variant="outline" 
                size="sm"
                className="border-gray-600 text-gray-300 hover:bg-gray-700 hover:text-white"
                onClick={() => navigate('/')}
              >
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Home
              </Button>
              <div>
                <h1 className="text-2xl font-bold bg-gradient-to-r from-cyan-400 to-blue-500 bg-clip-text text-transparent">
                  Projects Showcase
                </h1>
                <p className="text-sm text-gray-400">Innovation in Action</p>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-8">
        {/* Filter Section */}
        <div className="mb-8">
          <div className="flex items-center gap-4 mb-6">
            <Target className="w-5 h-5 text-cyan-400" />
            <span className="text-lg font-semibold text-white">Filter by Category:</span>
          </div>
          <div className="flex flex-wrap gap-3">
            {categories.map((category) => (
              <Button
                key={category}
                variant={selectedCategory === category ? "default" : "outline"}
                size="sm"
                className={`transition-all duration-300 ${
                  selectedCategory === category 
                    ? "bg-gradient-to-r from-cyan-500 to-blue-600 text-white" 
                    : "border-gray-600 text-gray-300 hover:bg-gray-700 hover:text-white"
                }`}
                onClick={() => setSelectedCategory(category)}
              >
                {category}
              </Button>
            ))}
          </div>
        </div>

        {/* Projects Grid */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredProjects.map((project, index) => (
            <Card 
              key={project.id}
              className={`group bg-gradient-to-br from-gray-800/50 to-gray-900/50 backdrop-blur-sm border border-gray-700/50 hover:border-cyan-400/50 transition-all duration-500 hover:transform hover:scale-105 cursor-pointer overflow-hidden animate-fade-in-up`}
              style={{ animationDelay: `${index * 100}ms` }}
              onClick={() => openProjectDetail(project)}
            >
              {/* Project Image */}
              <div className="relative h-48 overflow-hidden">
                <img 
                  src={project.image} 
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                  loading="lazy"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>
                
                {/* Status Badge */}
                <div className="absolute top-4 left-4">
                  <Badge className={getStatusColor(project.status)}>
                    {project.status}
                  </Badge>
                </div>

                {/* Category Badge */}
                <div className="absolute top-4 right-4">
                  <Badge className={getCategoryColor(project.category)}>
                    {project.category}
                  </Badge>
                </div>
              </div>

              <CardHeader className="pb-4">
                <CardTitle className="text-xl font-bold text-white group-hover:text-cyan-400 transition-colors duration-300 line-clamp-2">
                  {project.title}
                </CardTitle>
                <div className="flex items-center gap-4 text-sm text-gray-400">
                  <div className="flex items-center">
                    <Calendar className="w-4 h-4 mr-1" />
                    {project.year}
                  </div>
                  <div className="flex items-center">
                    <Users className="w-4 h-4 mr-1" />
                    {project.teamSize}
                  </div>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                <p className="text-gray-300 text-sm leading-relaxed line-clamp-3">
                  {project.description}
                </p>

                {/* Technologies */}
                <div className="flex flex-wrap gap-2">
                  {project.tech.slice(0, 3).map((tech, techIndex) => (
                    <Badge 
                      key={techIndex}
                      variant="outline"
                      className="border-gray-600 text-gray-300 text-xs"
                    >
                      {tech}
                    </Badge>
                  ))}
                  {project.tech.length > 3 && (
                    <Badge variant="outline" className="border-gray-600 text-gray-400 text-xs">
                      +{project.tech.length - 3} more
                    </Badge>
                  )}
                </div>

                {/* View Details */}
                <div className="flex items-center justify-between pt-2">
                  <div className="flex items-center text-cyan-400 text-sm font-semibold group-hover:translate-x-1 transition-transform duration-300">
                    <span>View Details</span>
                    <ChevronRight className="w-4 h-4 ml-1" />
                  </div>
                  <div className="text-gray-500 text-xs">
                    Click to explore
                  </div>
                </div>
              </CardContent>

              {/* Glow Effect */}
              <div className="absolute inset-0 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none shadow-2xl shadow-cyan-500/10"></div>
            </Card>
          ))}
        </div>

        {/* No Results */}
        {filteredProjects.length === 0 && (
          <div className="text-center py-16">
            <div className="text-6xl mb-4">🔍</div>
            <h3 className="text-2xl font-bold text-white mb-2">No projects found</h3>
            <p className="text-gray-400">Try selecting a different category filter.</p>
          </div>
        )}
      </main>

      {/* Project Detail Modal */}
      {selectedProject && (
        <div className="fixed inset-0 z-50 bg-black/95 flex items-center justify-center p-4 overflow-y-auto">
          <div className="relative max-w-4xl w-full max-h-full bg-gradient-to-br from-gray-800/90 to-gray-900/90 backdrop-blur-sm rounded-2xl border border-gray-700/50 overflow-hidden">
            {/* Close Button */}
            <button
              className="absolute top-6 right-6 z-10 p-2 rounded-full bg-black/50 text-white hover:bg-black/70 transition-colors duration-300"
              onClick={closeProjectDetail}
            >
              <ArrowLeft className="w-5 h-5" />
            </button>

            {/* Project Image Header */}
            <div className="relative h-64 overflow-hidden">
              <img 
                src={selectedProject.image} 
                alt={selectedProject.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent"></div>
              
              <div className="absolute bottom-6 left-6 right-16">
                <div className="flex items-center gap-3 mb-3">
                  <Badge className={getStatusColor(selectedProject.status)}>
                    {selectedProject.status}
                  </Badge>
                  <Badge className={getCategoryColor(selectedProject.category)}>
                    {selectedProject.category}
                  </Badge>
                </div>
                <h2 className="text-3xl font-bold text-white mb-2">{selectedProject.title}</h2>
                <div className="flex items-center gap-6 text-gray-300">
                  <div className="flex items-center">
                    <Calendar className="w-4 h-4 mr-2" />
                    {selectedProject.year}
                  </div>
                  <div className="flex items-center">
                    <Users className="w-4 h-4 mr-2" />
                    {selectedProject.teamSize}
                  </div>
                  <div className="flex items-center">
                    <Clock className="w-4 h-4 mr-2" />
                    {selectedProject.duration}
                  </div>
                </div>
              </div>
            </div>

            {/* Project Details Content */}
            <div className="p-8 space-y-8">
              {/* Description */}
              <div>
                <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                  <Target className="w-5 h-5 mr-2 text-cyan-400" />
                  Project Overview
                </h3>
                <p className="text-gray-300 leading-relaxed text-lg">
                  {selectedProject.fullDescription}
                </p>
              </div>

              {/* Technologies */}
              <div>
                <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                  <Code className="w-5 h-5 mr-2 text-cyan-400" />
                  Technologies Used
                </h3>
                <div className="flex flex-wrap gap-3">
                  {selectedProject.tech.map((tech, index) => (
                    <Badge 
                      key={index}
                      className="bg-gray-700/50 text-gray-200 border-gray-600 px-3 py-1"
                    >
                      {tech}
                    </Badge>
                  ))}
                </div>
              </div>

              {/* Challenges & Outcomes */}
              <div className="grid md:grid-cols-2 gap-8">
                <div>
                  <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                    <Target className="w-5 h-5 mr-2 text-orange-400" />
                    Key Challenges
                  </h3>
                  <ul className="space-y-2">
                    {selectedProject.challenges.map((challenge, index) => (
                      <li key={index} className="text-gray-300 flex items-start">
                        <span className="text-orange-400 mr-2">•</span>
                        {challenge}
                      </li>
                    ))}
                  </ul>
                </div>

                <div>
                  <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                    <Trophy className="w-5 h-5 mr-2 text-green-400" />
                    Key Outcomes
                  </h3>
                  <ul className="space-y-2">
                    {selectedProject.outcomes.map((outcome, index) => (
                      <li key={index} className="text-gray-300 flex items-start">
                        <span className="text-green-400 mr-2">•</span>
                        {outcome}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-col md:flex-row gap-4 pt-6 border-t border-gray-700">
                <Button 
                  className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white flex-1"
                  onClick={() => {
                    // In a real app, this would link to project repository or documentation
                    alert("Project repository would open here!");
                  }}
                >
                  <ExternalLink className="w-4 h-4 mr-2" />
                  View Repository
                </Button>
                <Button 
                  variant="outline"
                  className="border-gray-600 text-gray-300 hover:bg-gray-700 hover:text-white flex-1"
                  onClick={closeProjectDetail}
                >
                  Close Details
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProjectsShowcase;